<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Donna</title>
<style>
    body, html {
        margin: 0;
        padding: 0;
        background: #44283b;
        height: 100%;
        overflow: hidden;
    }

    p {
        margin: 0;
        font-size: 8px;
        line-height: 8px;
        text-align: justify;
        word-break: break-all;
        background: url('https://drive.google.com/thumbnail?id=1Y8VK4cAowmOimfRhSwVozxpoh-pSu62X&sz=w1000') no-repeat center / cover;
        background-attachment: fixed;
        -webkit-background-clip: text;
        background-clip: text;
        -webkit-text-fill-color: transparent;
        color: transparent;
        width: 100vw;
        height: 100vh;
    }
</style>
</head>
<body>

<p id="hex-text">

</p>

<script>
    const textElement = document.getElementById('hex-text');
    const originalText = textElement.innerText;
    textElement.innerText = originalText.repeat(150);
</script>

</body>
</html>
